import json
from collections import Counter
types=Counter()
events=[]
for line in open('trajectory.jsonl',errors='replace'):
    try: e=json.loads(line)
    except Exception: types['<nonjson>']+=1; continue
    types[e.get('type')]+=1
    events.append(e)
print(types)
# print message_end events brief
n=0
for e in events:
    if e.get('type')=='message_end':
        m=e.get('message',{})
        role=m.get('role')
        content=m.get('content')
        out=[]
        if isinstance(content,list):
            for c in content:
                t=c.get('type')
                if t=='text': out.append('TEXT:'+c.get('text','')[:300].replace('\n','\\n'))
                elif t=='thinking': out.append('THINK(%d)'%len(c.get('thinking','') or ''))
                elif t=='toolCall': out.append('CALL:'+c.get('name','')+' '+json.dumps(c.get('arguments'))[:400])
                else: out.append(t+':'+json.dumps(c)[:300])
        else:
            out.append(str(content)[:300])
        extra={k:m.get(k) for k in ('stopReason','errorMessage','toolName','isError') if m.get(k) is not None}
        n+=1
        print(n,role,extra,' | '.join(out)[:700])
EOF

